10	// multiPlanBody wraps configuration and priorState fragments in a plan
11	// request declaring the two resource types a and b.
12	func multiPlanBody(configResources, stateResources string) string {
13		return `{
14		  "configuration": {
15		    "resourceTypes": [
16		      {"name": "a", "schema": {"type": "object", "additionalProperties": true}},
17		      {"name": "b", "schema": {"type": "object", "additionalProperties": true}}
18		    ],
19		    "resources": ` + configResources + `
20		  },
21		  "priorState": {
22		    "resources": ` + stateResources + `
23		  }
24		}`
25	}
26	
27	// multiStateConfigBody builds a state-apply envelope declaring types a and b.
28	func multiStateConfigBody(configResources string) string {
29		return `{
30		  "configuration": {
31		    "resourceTypes": [
32		      {"name": "a", "schema": {"type": "object", "additionalProperties": true}},
33		      {"name": "b", "schema": {"type": "object", "additionalProperties": true}}
34		    ],
35		    "resources": ` + configResources + `
36		  }
37		}`
38	}
39	
40	// typedEntry is a configuration resource entry with an explicit type.
41	func typedEntry(address, typ, dependsOn string) string {
42		entry := `{"address": "` + address + `", "type": "` + typ + `", "properties": {}`
43		if dependsOn != "" {
44			entry += `, "dependsOn": ` + dependsOn
45		}
46		return entry + `}`
47	}
