55		// plus deletes of old-a (type a) and old-b (type b).
56		body := multiPlanBody(
57			`[`+typedEntry("u1", "a", `[]`)+`,`+typedEntry("u2", "b", `["u1"]`)+`,`+typedEntry("u3", "b", `[]`)+`]`,
58			`[`+stateEntry("u3", "a", `{}`, `[]`)+`,`+stateEntry("old-a", "a", `{}`, `[]`)+`,`+stateEntry("old-b", "b", `{}`, `[]`)+`]`)
59		res := doApply(t, handler, body, nil)
