77		if update.Before == nil || update.Before.Type != "a" || update.After == nil || update.After.Type != "b" {
78			t.Fatalf("type-changing update handed over as %+v", update)
79		}
80		// Deletes routed by the before snapshot's type.
81		if pb.calls[0].Before == nil || pb.calls[0].Before.Type != "b" || pb.calls[0].After != nil {
82			t.Fatalf("delete handed over as %+v", pb.calls[0])
83		}
84	}
