91			`[]`)
92		res := doApply(t, handler, body, nil)
93		if res.status != http.StatusOK || !res.Valid {
94			t.Fatalf("got status=%d valid=%v errors=%v", res.status, res.Valid, res.Errors)
95		}
96		if got := providerCallsSummary(shared.calls); got != "create:u1|create:u2" {
97			t.Fatalf("shared provider calls = %q", got)
98		}
99	}
