101	func TestMultiApplyEmptyPlanSucceedsWithoutRegistry(t *testing.T) {
102		for name, handler := range map[string]http.Handler{
103			"nil registry":   HandlerWithProviders(nil),
104			"empty registry": HandlerWithProviders(map[string]Provider{}),
105		} {
