type countingObserverProvider struct {
	err      error
	observes int
	applies  int
}

func (p *countingObserverProvider) Apply(ChangeRequest) error {
	p.applies++
	return nil
}

func (p *countingObserverProvider) Observe(context.Context, string) (*Snapshot, error) {
	p.observes++
	return nil, p.err
}

