// cancelDuringCompensationProvider succeeds on every forward create but, on
// the first compensation call, cancels the request context and returns a
// retryable error, so the retry gate trips before attempt 2.
type cancelDuringCompensationProvider struct {
	cancel context.CancelFunc
	calls  []ChangeRequest
}

func (p *cancelDuringCompensationProvider) Apply(req ChangeRequest) error {
	p.calls = append(p.calls, req)
	if req.Action == "delete" {
		p.cancel()
		return &retryableErr{msg: "retry me", retryable: true}
	}
	return nil
}

func TestApplyRollbackCompensationAbortsRetryWhenContextEnds(t *testing.T) {
	ctx, cancel := context.WithCancel(context.Background())
	provider := &cancelDuringCompensationProvider{cancel: cancel}
	// a fails forward plainly; b is the lone success to compensate.
	body := applyBody(`[`+resEntry("b", `[]`)+`,`+resEntry("a", `[]`)+`]`, `[]`, rollbackFlag)
	_ = body
	res := doApply(t, HandlerWithProvider(&failingForwardWrapper{
		inner:  provider,
		failAt: "a",
	}), body, ctx)
	if res.status != http.StatusBadGateway {
		t.Fatalf("status = %d", res.status)
	}
	if res.RollbackErrors == nil || len(*res.RollbackErrors) != 1 {
		t.Fatalf("rollbackErrors = %v", res.RollbackErrors)
	}
	re := (*res.RollbackErrors)[0]
	if re.Code != codeRollbackError || re.Message != context.Canceled.Error() || re.Path != "/rollbacks/0" {
		t.Fatalf("rollback error = %+v, want context cancellation at /rollbacks/0", re)
	}
}

// failingForwardWrapper wraps a provider used for the context test: forward
// creates succeed except for failAt, which fails with a plain error; all
// other calls delegate.
type failingForwardWrapper struct {
	inner  *cancelDuringCompensationProvider
	failAt string
}

func (w *failingForwardWrapper) Apply(req ChangeRequest) error {
	if req.Action == "create" && req.Address == w.failAt && req.Attempt == 1 {
		return errors.New("forward boom")
	}
	return w.inner.Apply(req)
}

