15	// applyBody builds a POST /v1/apply envelope of the same shape as planBody,
16	// with an extra trailing envelope fragment (e.g. a rollbackOnError field).
17	func applyBody(configResources, stateResources, extra string) string {
18		return `{
19		  "configuration": {
20		    "resourceTypes": [{"name": "t", "schema": {"type": "object", "additionalProperties": true}}],
21		    "resources": ` + configResources + `
22		  },
23		  "priorState": {
24		    "resources": ` + stateResources + `
25		  }` + extra + `
26		}`
27	}
28	
29	// multiApplyBody is the two-type counterpart of applyBody.
30	func multiApplyBody(configResources, stateResources, extra string) string {
31		return `{
32		  "configuration": {
33		    "resourceTypes": [
34		      {"name": "a", "schema": {"type": "object", "additionalProperties": true}},
35		      {"name": "b", "schema": {"type": "object", "additionalProperties": true}}
36		    ],
37		    "resources": ` + configResources + `
38		  },
39		  "priorState": {
40		    "resources": ` + stateResources + `
41		  }` + extra + `
42		}`
43	}
44	
45	const rollbackFlag = `,
46		  "rollbackOnError": true`
47	
48	// rollbackProvider scripts failures by the full shape of a call, so the
49	// forward update (before v1 -> after v2) and its compensating update (before
50	// v2 -> after v1) are independently scriptable despite sharing action and
51	// address.
52	type rollbackProvider struct {
53		mu       sync.Mutex
54		failures map[string]map[int]error // signature -> 1-based attempts that fail
55		calls    []ChangeRequest
56	}
57	
58	func rollbackSig(req ChangeRequest) string {
59		snap := func(s *Snapshot) string {
60			if s == nil {
61				return "-"
62			}
63			v := ""
64			if s.Properties != nil {
65				if raw, ok := s.Properties["v"]; ok {
66					v = fmt.Sprintf("%v", raw)
67				}
68			}
69			return s.Type + ":" + v
70		}
71		return req.Action + "|" + req.Address + "|" + snap(req.Before) + "->" + snap(req.After)
72	}
73	
74	func (p *rollbackProvider) Apply(req ChangeRequest) error {
75		p.mu.Lock()
76		defer p.mu.Unlock()
77		p.calls = append(p.calls, req)
78		if byAttempt, ok := p.failures[rollbackSig(req)]; ok {
79			if err, fail := byAttempt[req.Attempt]; fail {
80				return err
81			}
82		}
83		return nil
84	}
85	
86	func (p *rollbackProvider) callsLocked() []ChangeRequest {
87		p.mu.Lock()
88		defer p.mu.Unlock()
89		out := make([]ChangeRequest, len(p.calls))
90		copy(out, p.calls)
91		return out
92	}
93	
